actionConfiguration.body:
async function () {
  try {
    await ApiLogin.run();
    storeValue("token", ApiLogin.data.token);
    showAlert("Login exitoso", "success");
    await ApiMe.run();
    const role = ApiMe.data.role;
    storeValue("role", role);
    switch (role) {
      case "admin":
        navigateTo("DashboardAdmin");
        break;
      case "analista":
        navigateTo("DashboardAnalista");
        break;
      case "postulante":
        navigateTo("Dashboard");
        break;
      case "evaluador":
        navigateTo("DashboardEvaluador");
        break;
      case "instructor":
        navigateTo("DashboardInstructor");
        break;
      default:
        showAlert("Rol desconocido: " + role, "error");
        navigateTo("Login");
    }
  } catch (error) {
    showAlert(ApiLogin.data.message);
  }
}

